const AppError = require('../utils/AppError')

// The table accepts at most 255 characters. The character set keeps keys
// header-safe and readable; UUIDs generated by the client fit this format.
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9._~-]{8,255}$/

function validateIdempotencyKey(value) {
  if (typeof value !== 'string' || !IDEMPOTENCY_KEY_PATTERN.test(value)) {
    throw new AppError('A valid Idempotency-Key header is required (8–255 letters, numbers, dots, underscores, tildes, or hyphens).', 400)
  }
  return value
}

module.exports = { validateIdempotencyKey }
